 const materials={pole:new T.MeshLambertMaterial({color:'#8f9691'}),red:new T.MeshLambertMaterial({color:'#b72023'}),white:new T.MeshLambertMaterial({color:'#e5e2d4'}),black:new T.MeshLambertMaterial({color:'#202621'}),lamp:new T.MeshBasicMaterial({color:'#ffffff'})};
 function label(text,background){if(typeof document==='undefined')return null;const c=document.createElement('canvas');c.width=c.height=256;const p=c.getContext('2d');p.fillStyle=background;p.fillRect(0,0,256,256);p.fillStyle=text==='STOP'?'white':'#20221e';p.font='bold '+(text==='STOP'?68:42)+'px Arial';p.textAlign='center';p.textBaseline='middle';if(text==='STOP')p.fillText(text,128,132,200);else{p.fillText('GIVE',128,92,170);p.fillText('WAY',128,134,120)}const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;return t}
