 function speedFace(limit){if(typeof document==='undefined')return null;const c=document.createElement('canvas');c.width=c.height=256;const p=c.getContext('2d');p.fillStyle='#c41f24';p.beginPath();p.arc(128,128,128,0,Math.PI*2);p.fill();p.fillStyle='#f2f0e6';p.beginPath();p.arc(128,128,100,0,Math.PI*2);p.fill();p.fillStyle='#151714';p.font='bold '+(limit>=100?92:116)+'px Arial';p.textAlign='center';p.textBaseline='middle';p.fillText(String(limit),128,136,170);const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.anisotropy=4;return t}
 batch('speed backs',new T.CircleGeometry(.42,24).rotateY(Math.PI),materials.pole);for(const v of speedValues)batch('speed '+v,new T.CircleGeometry(.4,32),new T.MeshLambertMaterial({map:speedFace(v),color:typeof document==='undefined'?'#e5e2d4':'white'}));
 const dummy=new T.Object3D(),color=new T.Color(),fallQuaternion=new T.Quaternion(),fallAxis=new T.Vector3(),fallPosition=new T.Vector3();function put(name,p,x,y,z,sx=1,sy=1,sz=1,tint){const mesh=meshes[name],i=mesh.count;if(i>=mesh.instanceMatrix.count)return;mesh.count++;dummy.position.set(x,y,z);dummy.rotation.set(0,p.yaw||0,0);dummy.scale.set(sx,sy,sz);if(p.brokenAt!==undefined&&name!=='stop lines'){const t=T.MathUtils.smoothstep(rules.clock-p.brokenAt,0,.65);fallAxis.set(p.fallZ,0,-p.fallX).normalize();fallQuaternion.setFromAxisAngle(fallAxis,t*1.53);fallPosition.set(x-p.x,y-p.y,z-p.z).applyQuaternion(fallQuaternion);dummy.position.set(p.x+fallPosition.x,p.y+.05+fallPosition.y,p.z+fallPosition.z);dummy.quaternion.premultiply(fallQuaternion)}dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);if(tint)mesh.setColorAt(i,color.set(tint))}
