 return{plans,meshes,update,impact(car,from,to){let broken=0;const m=car.model||{},speed=Math.abs(car.velocity||0),yaw=car.yaw||0,reach=(m.length||4.5)/2+1;for(let ix=Math.floor((to.x-reach)/32);ix<=Math.floor((to.x+reach)/32);ix++)for(let iz=Math.floor((to.z-reach)/32);iz<=Math.floor((to.z+reach)/32);iz++)for(const p of cells.get(ix+','+iz)||[]){if(p.brokenAt!==undefined||Math.abs(from.y-p.y)>2||speed<(p.kind==='signal'?6:1.8))continue;const hit=[from,to].some(q=>{const x=p.x-q.x,z=p.z-q.z;return Math.abs(x*Math.cos(yaw)-z*Math.sin(yaw))<(m.width||1.8)/2+.14&&Math.abs(x*Math.sin(yaw)+z*Math.cos(yaw))<(m.length||4.5)/2+.18});if(!hit)continue;p.brokenAt=rules.clock;p.fallX=-Math.sin(yaw)*Math.sign(car.velocity);p.fallZ=-Math.cos(yaw)*Math.sign(car.velocity);car.velocity*=p.kind==='signal'?.72:.94;car.signImpacts=(car.signImpacts||0)+1;broken++}if(broken)next=-1;return broken},free(x,z,y){for(let ix=-1;ix<=1;ix++)for(let iz=-1;iz<=1;iz++)for(const p of cells.get((Math.floor(x/32)+ix)+','+(Math.floor(z/32)+iz))||[])if(p.brokenAt===undefined&&(y===undefined||Math.abs(y-2-p.y)<3)&&Math.hypot(x-p.x,z-p.z)<.16)return false;return true},get stats(){return{signs:plans.filter(p=>p.kind!=='signal').length,speedSigns:plans.filter(p=>p.kind==='speed').length,signals:plans.filter(p=>p.kind==='signal').length}}};
